def raw(type, f) when is_function(f, 1) do
  type
  |> fix_type()
  |> :poolboy.transaction(fn pid ->
    case GenServer.call(pid, :conn) do
      %Rambla.Connection{conn_pid: pid} -> {:ok, f.(pid)}
      _ -> {:error, :connection}
    end
  end)
end

